qualified_questions.sparql_query:
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?device
WHERE {
    ?device rdf:type ?type .
    ?type rdfs:subClassOf* saref:Device .
    FILTER NOT EXISTS { 
        ?sensor rdf:type saref:Sensor .
        ?device rdfs:subClassOf* ?sensor .
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?device ?function
WHERE {
    ?device rdf:type saref:Device .
    OPTIONAL { 
        ?device s4envi:hasFunction ?function . 
    }
}

PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX saref: <https://www.saref.etsi.org/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?device ?sensor ?measurement ?location ?transmissionPeriod ?geometry
WHERE {
    ?device s4envi:contains ?sensor .
    ?sensor saref:makesMeasurement ?measurement .
    ?device wgs84:location ?location .
    ?device s4envi:hasTransmissionPeriod ?transmissionPeriod .
    ?device s4envi:hasGeometry ?geometry .
    OPTIONAL { 
        ?sensor saref:relatesToProperty ?property . 
    }
    OPTIONAL { 
        ?device s4envi:affectsProperty ?affectedProperty . 
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://www.sensormeasurement.appspot.com/ont/s4envi/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT ?device
WHERE {
    ?device wgs84:location ?location .
    FILTER NOT EXISTS {
        ?otherDevice wgs84:location ?location .
        FILTER (?otherDevice != ?device)
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.eurosix.org/vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?device ?representation
WHERE {
    ?device s4envi:hasDigitalRepresentation ?representation .
    FILTER NOT EXISTS {
        ?device s4envi:hasDigitalRepresentation ?otherRepresentation .
        FILTER (?representation != ?otherRepresentation)
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?document ?title 
WHERE {
    ?document dcterms:issued ?issued .
    ?document dcterms:title ?title .
    FILTER NOT EXISTS { 
        ?document dcterms:modified ?modified .
        FILTER (?modified > ?issued)
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?source
WHERE {
    ?vocabulary vann:preferredNamespaceUri ?namespaceUri .
    ?vocabulary vann:preferredNamespacePrefix ?prefix .
    OPTIONAL { ?vocabulary dcterms:source ?source . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?source ?license
WHERE {
    ?term dcterms:description ?description .
    OPTIONAL { ?term dcterms:source ?source . }
    OPTIONAL { ?term dcterms:license ?license . }
    FILTER (?description != "")
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX vann: <http://purl.org/vocab/vann/>

SELECT ?resource ?license ?modification
WHERE {
    ?resource dcterms:license ?license .
    OPTIONAL { 
        ?resource dcterms:modified ?modification . 
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref: <http://www.saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>

SELECT ?unit
WHERE {
    ?unit rdf:type saref:UnitOfMeasure .
    FILTER NOT EXISTS { 
        { ?unit rdf:type s4envi:LengthUnit } 
        UNION 
        { ?unit rdf:type s4envi:FrequencyUnit } 
    } .
}

PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX saref: <https://www.saref.etsi.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?lightProperty ?unitOfMeasure
WHERE {
    ?lightProperty rdf:type s4envi:LightProperty .
    OPTIONAL { 
        ?lightProperty saref:hasUnit ?unitOfMeasure .
        FILTER (?unitOfMeasure != saref:UnitOfMeasure)
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref: <https://www.saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>

SELECT ?unit ?lightProperty
WHERE {
    ?unit rdf:type ?unitType .
    ?lightProperty rdf:type ?lightPropertyType .
    FILTER (?unit != ?lightProperty) .
    {
        { ?unitType rdfs:subClassOf* saref:UnitOfMeasure . }
        UNION
        { ?unitType rdfs:subClassOf* s4envi:LengthUnit . }
        UNION
        { ?unitType rdfs:subClassOf* s4envi:FrequencyUnit . }
    }
    {
        ?lightPropertyType rdfs:subClassOf* s4envi:LightProperty .
    }
    ?unit rdf:type/s4envi:LengthUnit|s4envi:FrequencyUnit ? .
    ?lightProperty rdf:type/s4envi:LightProperty ? .
}

PREFIX s4envi: <http://www.saref.org/saref4envi/>
PREFIX saref: <http://www.saref.org/>
PREFIX om-1.8: <http://www.wurvoc.org/vocabularies/om-1.8/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?centimetre ?metre ?kilometre
WHERE {
    BIND(om-1.8:centimetre AS ?centimetre)
    BIND(om-1.8:metre AS ?metre)
    BIND(om-1.8:kilometre AS ?kilometre)
    FILTER EXISTS { ?centimetre rdf:type s4envi:LengthUnit }
    FILTER EXISTS { ?metre rdf:type s4envi:LengthUnit }
    FILTER EXISTS { ?kilometre rdf:type s4envi:LengthUnit }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://www.saref.eu/s4envi/>
PREFIX saref: <http://www.saref.eu/>
PREFIX om: <http://www.wurvoc.org/vocabularies/om-1.8/>

SELECT ?x
WHERE {
    ?x rdf:type saref:Property ;
       saref:isMeasuredBy om:reciprocal_year .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?creator ?profile
WHERE {
    <https://saref.etsi.org/saref4envi/> dcterms:creator ?creator .
    OPTIONAL { 
        ?creator foaf:homepage ?profile .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX saref4envi: <https://saref.etsi.org/saref4envi/>

SELECT ?contributor ?role
WHERE {
    {
        saref4envi: dcterms:creator ?contributor .
        OPTIONAL { ?contributor rdf:type ?role }
    }
    UNION
    {
        saref4envi: dcterms:contributor ?contributor .
        OPTIONAL { ?contributor rdf:type ?role }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?organization
WHERE {
    { 
        <https://saref.etsi.org/saref4envi/> dcterms:creator ?creator .
        BIND(?creator AS ?organization)
    } UNION {
        <https://saref.etsi.org/saref4envi/> dcterms:publisher ?publisher .
        BIND(?publisher AS ?organization)
    } UNION {
        <https://saref.etsi.org/saref4envi/> dcterms:contributor ?contributor .
        BIND(?contributor AS ?organization)
    }
}

PREFIX saref: <https://saref.etsi.org/saref4envi/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?version ?source ?seeAlso
WHERE {
    <https://saref.etsi.org/saref4envi/> rdf:type owl:Ontology .
    <https://saref.etsi.org/saref4envi/> owl:versionIRI ?version .
    OPTIONAL { <https://saref.etsi.org/saref4envi/> dcterms:source ?source . }
    OPTIONAL { <https://saref.etsi.org/saref4envi/> rdfs:seeAlso ?seeAlso . }
}

PREFIX saref4envi: <https://saref.etsi.org/saref4envi/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?application ?support
WHERE {
    BIND("environmental monitoring applications" AS ?application) .
    BIND("decision-making" AS ?support) .
    FILTER EXISTS {
        ?s dcterms:description ?description .
        FILTER regex(?description, "environmental monitoring", "i") .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX saref: <https://saref.etsi.org/saref4envi/>

SELECT ?source
WHERE {
    <https://saref.etsi.org/saref4envi/> dcterms:source ?source .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX saref: <https://saref.etsi.org/saref4envi/>

SELECT ?publisher
WHERE {
    <https://saref.etsi.org/saref4envi/> dcterms:publisher ?publisher .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?version
WHERE {
    ?s owl:imports <https://saref.etsi.org/core/v3.2.1/> .
    ?s owl:versionIRI ?version .
    FILTER NOT EXISTS { ?s a owl:Ontology }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?information
WHERE {
    ?s dcterms:license <https://forge.etsi.org/etsi-software-license> .
    OPTIONAL { ?s rdf:type ?type . }
    OPTIONAL { ?s rdfs:seeAlso ?seeAlso . }
    OPTIONAL { ?s dcterms:source ?source . }
    OPTIONAL { ?s dcterms:publisher ?publisher . }
    OPTIONAL { ?s owl:versionIRI ?version . }
    BIND(CONCAT("License: ", STR(<https://forge.etsi.org/etsi-software-license>), "\nType: ", COALESCE(STR(?type), "Not specified"), "\nSee Also: ", COALESCE(STR(?seeAlso), "Not specified"), "\nSource: ", COALESCE(STR(?source), "Not specified"), "\nPublisher: ", COALESCE(STR(?publisher), "Not specified"), "\nVersion: ", COALESCE(STR(?version), "Not specified")) AS ?information)
    FILTER (?s = <https://saref.etsi.org/saref4envi/>)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.example/>

SELECT ?component ?subComponent 
WHERE {
    ?component rdf:type ?type .
    ?subComponent s4envi:isComponentOf ?component .
    FILTER NOT EXISTS { 
        ?subComponent s4envi:hasComponent ?subSubComponent .
    }
    BIND(s4envi:Component AS ?type)
}

PREFIX s4envi: <http://s4envi.eurocean.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?component1 ?relation ?component2
WHERE {
    {
        ?component1 s4envi:hasComponent ?component2 .
        BIND(s4envi:hasComponent AS ?relation) .
    }
    UNION
    {
        ?component1 s4envi:isComponentOf ?component2 .
        BIND(s4envi:isComponentOf AS ?relation) .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.example/>

SELECT ?component1 ?component2
WHERE {
    ?component1 s4envi:hasComponent ?mid .
    ?mid s4envi:hasComponent ?component2 .
    FILTER NOT EXISTS { 
        ?component1 s4envi:isComponentOf ?x .
        ?x s4envi:isComponentOf ?component2
    }
}

PREFIX s4envi: <http://s4envi.example/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?component ?device1 ?device2
WHERE {
    ?component s4envi:isComponentOf ?device1 .
    ?device1 s4envi:isComponentOf ?device2 .
    FILTER NOT EXISTS { 
        ?component s4envi:isComponentOf ?device2 .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.example/>

SELECT ?component ?system
WHERE {
    { ?system s4envi:hasComponent ?component }
    UNION
    { ?component s4envi:isComponentOf ?system }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.example/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property ?constraint
WHERE {
    {
        s4envi:hasComponent rdf:type ?type .
        FILTER(?type = owl:TransitiveProperty || ?type = owl:ObjectProperty)
        BIND(s4envi:hasComponent AS ?property)
        BIND("Transitive and Object Property" AS ?constraint)
    } UNION {
        s4envi:isComponentOf rdf:type ?type .
        FILTER(?type = owl:TransitiveProperty || ?type = owl:ObjectProperty)
        BIND(s4envi:isComponentOf AS ?property)
        BIND("Transitive and Object Property" AS ?constraint)
    } UNION {
        s4envi:hasComponent owl:inverseOf ?inverse .
        BIND(s4envi:hasComponent AS ?property)
        BIND(?inverse AS ?constraint)
    }
}

PREFIX s4envi: <http://s4envi.example/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?device
WHERE {
    ?device a s4envi:Device .
    FILTER NOT EXISTS {
        ?device s4envi:isConnectedTo ?otherDevice .
        ?otherDevice a s4envi:Device .
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?measurement
WHERE {
    ?measurement rdf:type saref:Measurement .
    FILTER NOT EXISTS {
        { 
            ?measurement rdf:type ?type .
            ?type owl:disjointWith wgs84:SpatialThing 
        } 
        UNION 
        { 
            ?measurement rdf:type ?type .
            ?type rdfs:subClassOf* ?superType .
            ?superType owl:disjointWith wgs84:SpatialThing
        }
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?measurement ?unitOfMeasure
WHERE {
    ?measurement rdf:type saref:Measurement .
    ?unitOfMeasure rdf:type saref:UnitOfMeasure .
    FILTER NOT EXISTS { 
        ?measurement owl:disjointWith ?unitOfMeasure .
    }
    FILTER NOT EXISTS { 
        ?unitOfMeasure owl:disjointWith ?measurement 
    }
    ?measurement saref:hasUnit ?unitOfMeasure
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?property ?measurement
WHERE {
    ?measurement rdfs:subClassOf saref:Measurement .
    ?property rdf:type saref:Property .
    FILTER NOT EXISTS { 
        ?property owl:disjointWith ?measurement .
    }
    BIND(?measurement AS ?boundMeasurement)
    FILTER(EXISTS {
      ?boundMeasurement rdf:type ?type .
      ?type rdfs:subClassOf* saref:Measurement
    })
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?communicationProtocol ?digitalRepresentation
WHERE {
    ?communicationProtocol rdf:type s4envi:CommunicationProtocol .
    ?digitalRepresentation rdf:type s4envi:DigitalRepresentation .
    FILTER NOT EXISTS { 
        ?communicationProtocol owl:disjointWith ?digitalRepresentation .
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?geometry ?measurement
WHERE {
    ?measurement rdf:type saref:Measurement .
    ?geometry rdf:type s4envi:Geometry .
    FILTER NOT EXISTS {
        { ?measurement owl:disjointWith ?geometry }
        UNION
        { ?geometry owl:disjointWith ?measurement }
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?light ?measurement
WHERE {
    ?light rdf:type s4envi:Light .
    ?measurement rdf:type saref:Measurement .
    FILTER NOT EXISTS { 
        ?light ?p ?measurement . 
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?unitOfMeasure ?property
WHERE {
    ?unitOfMeasure rdf:type saref:UnitOfMeasure .
    ?property rdf:type saref:Property .
    FILTER NOT EXISTS { 
        ?unitOfMeasure owl:equivalentClass ?x .
        ?x owl:equivalentClass ?property 
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?class ?property
WHERE {
    ?class rdf:type owl:Class .
    ?class rdfs:subClassOf saref:Measurement .
    ?property rdf:type owl:Class .
    FILTER (?class != ?property) .
    { 
        ?class owl:disjointWith ?property .
    } UNION {
        ?property owl:disjointWith ?class .
    }
}
